---@language GLSL
local vs = [[
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif // GL_FRAGMENT_PRECISION_HIGH
 
attribute vec2 position;
varying vec2 textureCoordinate;

void main()
{
    textureCoordinate = position * 0.5 + 0.5;
    gl_Position = vec4(position, 0.0, 1.0);
}
]]

---@language GLSL
local fs = [[
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif // GL_FRAGMENT_PRECISION_HIGH

varying vec2 textureCoordinate;
uniform sampler2D inputImageTexture;

uniform vec2 imageSize;
uniform float groupOffset;
uniform float samplerRadius;

uniform float quad1[7];
uniform float quad2[7];
uniform float quad3[7];
uniform float quad4[7];

float random(vec2 seed) 
{
    return fract(sin(dot(seed, vec2(12.9898, 78.233))) * 43758.5453);
} 

vec4 blur(sampler2D tex, vec2 uv, vec2 samplerSteps, float radius)
{
    if (radius < 2.0)
    {
        return texture2D(tex, uv);
    }

    vec4 resultColor = vec4(0.0);

    float blurPixels = 0.0;
    float offset = random(uv) - 0.5;

    for (int i = 0; i <= 14; ++i)
    {
        if (float(i) > radius * 2.0) { break; }
        float k = float(i) - radius;
        float percent = (k + offset) / radius;
        float weight = 1.0 - abs(percent);
        vec2 coord = uv + samplerSteps * percent;
        resultColor += texture2D(tex, coord) * weight;
        blurPixels += weight;
    }
    return resultColor / blurPixels;
}
    
void main()
{
    float ratio = imageSize.x / imageSize.y;
    vec2 uv1 = vec2(1.0) - abs(mod(textureCoordinate + vec2(groupOffset, 0.0), 2.0) - vec2(1.0));
    vec2 uv2 = vec2(1.0) - abs(mod(textureCoordinate - vec2(groupOffset, 0.0), 2.0) - vec2(1.0));
    vec2 uv3 = vec2(1.0) - abs(mod(textureCoordinate - vec2(0.0, groupOffset * ratio), 2.0) - vec2(1.0));
    vec2 uv4 = vec2(1.0) - abs(mod(textureCoordinate + vec2(0.0, groupOffset * ratio), 2.0) - vec2(1.0));

    vec4 inputColor1 = vec4(0.0);
    vec4 inputColor2 = vec4(0.0);
    vec4 inputColor3 = vec4(0.0);
    vec4 inputColor4 = vec4(0.0);    

    float cols = 4.0;
    float rows = 7.0;


    for (int i = 0; i < 7; i = i + 1)
    {
        float currentRow1 = floor((quad1[i] - 1.0) / 4.0);
        float currentRow2 = floor((quad2[i] - 1.0) / 4.0);
        float currentRow3 = floor((quad3[i] - 1.0) / 4.0);
        float currentRow4 = floor((quad4[i] - 1.0) / 4.0);

        if (textureCoordinate.x > (1.0 / cols) * mod(quad1[i] - 1.0, cols) && 
            textureCoordinate.x <= (1.0 / cols) * (mod(quad1[i] - 1.0, cols) + 1.0) && 
            (textureCoordinate.y > currentRow1 * (1.0 / rows)) && 
            (textureCoordinate.y <= (currentRow1 + 1.0) * (1.0 / rows)))
        {
            inputColor1 = blur(inputImageTexture, uv1, vec2(samplerRadius * 1.5 / imageSize.x, 0.0), samplerRadius);
        }
    
        if (textureCoordinate.x > (1.0 / cols) * mod(quad2[i] - 1.0, cols) && 
            textureCoordinate.x <= (1.0 / cols) * (mod(quad2[i] - 1.0, cols) + 1.0) && 
            (textureCoordinate.y > currentRow2 * (1.0 / rows)) && 
            (textureCoordinate.y <= (currentRow2 + 1.0) * (1.0 / rows)))
        {
            inputColor2 = blur(inputImageTexture, uv2, vec2(samplerRadius * 1.5 / imageSize.x, 0.0), samplerRadius);
        }

        if (textureCoordinate.x > (1.0 / cols) * mod(quad3[i] - 1.0, cols) && 
            textureCoordinate.x <= (1.0 / cols) * (mod(quad3[i] - 1.0, cols) + 1.0) && 
            (textureCoordinate.y > currentRow3 * (1.0 / rows)) && 
            (textureCoordinate.y <= (currentRow3 + 1.0) * (1.0 / rows)))
        {
            inputColor3 = blur(inputImageTexture, uv3, vec2(0.0, samplerRadius * 1.5 / imageSize.y), samplerRadius);
        }

        if (textureCoordinate.x > (1.0 / cols) * mod(quad4[i] - 1.0, cols) && 
            textureCoordinate.x <= (1.0 / cols) * (mod(quad4[i] - 1.0, cols) + 1.0) && 
            (textureCoordinate.y > currentRow4 * (1.0 / rows)) && 
            (textureCoordinate.y <= (currentRow4 + 1.0) * (1.0 / rows)))
        {
            inputColor4 = blur(inputImageTexture, uv4, vec2(0.0, samplerRadius * 1.5 / imageSize.y), samplerRadius);
        }        
    }

    gl_FragColor = inputColor1 + inputColor2 + inputColor3 + inputColor4;
}

]]

SlicingSlide = {}

function SlicingSlide:matchWithId(effectId)
    return 'KFM KSkr SlicingSlide' == effectId
end

function SlicingSlide.createWithId(effectId)
    if not SlicingSlide:matchWithId(effectId) then
        return nil
    end
    local o = {
        program = {},
        vbo = 0,
        quad1Loc = 0,
        quad2Loc = 0,
        quad3Loc = 0,
        quad4Loc = 0        
    }
    o = newObject(o, SlicingSlide)
    o:init()
    return o;
end

function SlicingSlide:init()
    self.program = CGE.ProgramObject()
    self.program:bindAttribLocation('position', 0)
    self.program:initWithShaderStrings(vs, fs)
    
    local buffer = {}
    glGenBuffers(1,buffer)
    self.vbo = buffer[1]
    local vertices = {-1,-1,1,-1,-1,1,1,1}
    local verticesData = CGE.FloatBuffer:alloc(#vertices)
    verticesData:put(#vertices, vertices, 0)
    glBindBuffer(GL_ARRAY_BUFFER, self.vbo)
    glBufferData(GL_ARRAY_BUFFER, #vertices, verticesData:position(0), GL_STATIC_DRAW)

    self.program:bind()
    self.program:sendUniformi('inputImageTexture', 0)

    self.quad1Loc = self.program:uniformLocation("quad1")
    local quad1 = {1.0, 8.0, 11.0, 14.0, 17.0, 24.0, 27.0}
    glUniform1fv(self.quad1Loc, #quad1, quad1)

    self.quad2Loc = self.program:uniformLocation("quad2")
    local quad2 = {3.0, 6.0, 9.0, 16.0, 19.0, 22.0, 25.0}
    glUniform1fv(self.quad2Loc, #quad2, quad2)

    self.quad3Loc = self.program:uniformLocation("quad3")
    local quad3 = {2.0, 7.0, 12.0, 13.0, 18.0, 23.0, 28.0}
    glUniform1fv(self.quad3Loc, #quad3, quad3)

    self.quad4Loc = self.program:uniformLocation("quad4")
    local quad4 = {4.0, 5.0, 10.0, 15.0, 20.0, 21.0, 26.0}
    glUniform1fv(self.quad4Loc, #quad4, quad4)

    self.drawer = CGE.TextureDrawer:create()
end

function SlicingSlide:valueType(index)
    if index == 1 then
        return FM.AEValueType_OneDFloat
    elseif index == 2 then
        return FM.AEValueType_OneDFloat
    end
end

function SlicingSlide:updateValue(index, val1, val2, val3)
    self.program:bind()
    if index == 1 then
        self.program:sendUniformf("groupOffset", val1)
    elseif index == 2 then
        self.program:sendUniformf("samplerRadius", math.min(val1, 7.0))
    end
end

function SlicingSlide:resize(width, height)
    self.program:bind()
    self.program:sendUniformf("imageSize", width, height)
end

function SlicingSlide:render(outFBO, inputTex)
   glBindFramebuffer(GL_FRAMEBUFFER, outFBO)
   -- glViewport(0,0,1024,1024)
    self.program:bind()

    glActiveTexture(GL_TEXTURE0)
    glBindTexture(GL_TEXTURE_2D, inputTex)

    glBindBuffer(GL_ARRAY_BUFFER, self.vbo)
    glEnableVertexAttribArray(0)
    glVertexAttribPointer(0, 2, GL_FLOAT, GL_FALSE, 0, 0)
    
    glDrawArrays(GL_TRIANGLE_STRIP, 0, 4)
end

function SlicingSlide:onDestroy()
    glDeleteBuffers(1, {self.vbo})
end
